$_MODULE['<{priceandorder}prestashop>_tutorial_7f1b3b7557f81bb527614a601f1df990'] = 'Ziyaretçilerden istenecek isteğe bağlı alanları seçin (adres, telefon, adet...).';
$_MODULE['<{priceandorder}prestashop>_tutorial_cc3b0858bf5fcf55dc3e1daae0076461'] = 'Yönetim panelinizde Tasarım > Konumlar bölümüne gidin ve kenar çubuğu formunu göstermek için Priceandorder\'ın \"Sol sütun\" veya \"Sağ sütun\" kancasında, yüzen buton için ise \"Altbilgi\" kancasında etkin olduğundan emin olun.';
$_MODULE['<{priceandorder}prestashop>_tutorial_0431a668e8d90860362093b461947781'] = 'Mağazanızdan bir test talebi gönderin ve Fiyat Teklif Talepleri sekmesine ve e-posta kutunuza ulaştığını kontrol edin.';
